    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length();
        int n = s2.length();
        if (m + n != s3.length()) {
            return false;
        }

        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int j = 1; j <= n; j++) {
            dp[j] = dp[j - 1] && s2.charAt(j - 1) == s3.charAt(j - 1);
        }
        for (int i = 1; i <= m; i++) {
            dp[0] = dp[0] && s1.charAt(i - 1) == s3.charAt(i - 1);
            for (int j = 1; j <= n; j++) {
                char needed = s3.charAt(i + j - 1);
                boolean fromS1 = dp[j] && s1.charAt(i - 1) == needed;
                boolean fromS2 = dp[j - 1] && s2.charAt(j - 1) == needed;
                dp[j] = fromS1 || fromS2;
            }
        }
        return dp[n];
    }
}

class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        if (s1.length() + s2.length() != s3.length()) {
            return false;
        }
        Boolean[][] memo = new Boolean[s1.length() + 1][s2.length() + 1];
        return dfs(s1, s2, s3, 0, 0, memo);
    }

    private boolean dfs(String s1, String s2, String s3, int i, int j, Boolean[][] memo) {
        if (i == s1.length() && j == s2.length()) {
            return true;
        }
        if (memo[i][j] != null) {
            return memo[i][j];
        }

        int k = i + j;
        boolean ok = false;
        if (i < s1.length() && s1.charAt(i) == s3.charAt(k)) {
            ok = dfs(s1, s2, s3, i + 1, j, memo);
        }
        if (!ok && j < s2.length() && s2.charAt(j) == s3.charAt(k)) {
            ok = dfs(s1, s2, s3, i, j + 1, memo);
        }
        memo[i][j] = ok;
        return ok;
    }
}

class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length();
        int n = s2.length();
        if (m + n != s3.length()) {
            return false;
        }

        boolean[][] seen = new boolean[m + 1][n + 1];
        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        queue.add(new int[] {0, 0});
        seen[0][0] = true;

        while (!queue.isEmpty()) {
            int[] state = queue.removeFirst();
            int i = state[0];
            int j = state[1];
            if (i == m && j == n) {
                return true;
            }
            int k = i + j;
            if (i < m && !seen[i + 1][j] && s1.charAt(i) == s3.charAt(k)) {
                seen[i + 1][j] = true;
                queue.addLast(new int[] {i + 1, j});
            }
            if (j < n && !seen[i][j + 1] && s2.charAt(j) == s3.charAt(k)) {
                seen[i][j + 1] = true;
                queue.addLast(new int[] {i, j + 1});
            }
        }
        return false;
    }
}

class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length();
        int n = s2.length();
        if (m + n != s3.length()) {
            return false;
        }

        boolean[][] suffix = new boolean[m + 1][n + 1];
        suffix[m][n] = true;
        for (int i = m; i >= 0; i--) {
            for (int j = n; j >= 0; j--) {
                if (i == m && j == n) {
                    continue;
                }
                int k = i + j;
                boolean takeS1 = i < m && s1.charAt(i) == s3.charAt(k) && suffix[i + 1][j];
                boolean takeS2 = j < n && s2.charAt(j) == s3.charAt(k) && suffix[i][j + 1];
                suffix[i][j] = takeS1 || takeS2;
            }
        }
        return suffix[0][0];
    }
}
